script.deleting:
item -> {
  name = $item.get(`TestHandlersByExpression:Item#name`);
  counter = $item.get(`TestHandlersByExpression:Item#counter`);
  if ($name == "invalid",
    "not a function",
    if ($counter == null || $name == "no-reaction",
      null,
      arg -> $counter.set(`TestHandlersByExpression:Counter#log`, toString($counter.get(`TestHandlersByExpression:Counter#log`), "deleted:", $name, ":", if ($arg == null, "null", "other"), ";"))
    )
  );
}
